SELECT city, CASE WHEN sqft >= 14671 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, SIZE(COLLECT_SET(region)) AS num_regions, COUNT(CASE WHEN region = 'Central' THEN 1 END) AS central_count, COUNT(CASE WHEN city = 'Tokyo' THEN 1 END) AS tokyo_count, PERCENTILE_APPROX(sqft, 0.9) AS sqft_p90, ROUND(AVG(sqft), 2) AS avg_sqft, COUNT_IF(city = 'Singapore') AS singapore_events, RANK() OVER (PARTITION BY city ORDER BY COUNT(CASE WHEN city = 'Tokyo' THEN 1 END) DESC) AS tokyo_count_rank FROM stores GROUP BY city, CASE WHEN sqft >= 14671 THEN 'HIGH' ELSE 'LOW' END ORDER BY sqft_tier NULLS FIRST;
